<p><strong>قلعه فلک‌الافلاک</strong> — همان <strong>دژ شاپورخواست</strong> — شاخص‌ترین بنای تاریخی خرم‌آباد و یکی از شناخته‌شده‌ترین قلعه‌های ایران است؛ دژی بر بلندای تپه‌ای باستانی در مرکز شهر که از بیشتر نقاط خرم‌آباد دیده می‌شود. هسته اصلی بنا به دوره ساسانی نسبت داده می‌شود و لایه‌های بعدی، از آل بویه و اتابکان لر کوچک تا صفویه و قاجار، هر کدام چیزی به آن افزوده‌اند.</p>
<p>فلک‌الافلاک امروز فقط یک بنای دیدنی نیست؛ مجموعه‌ای زنده از موزه مردم‌شناسی و باستان‌شناسی لرستان، چای‌خانه سنتی و بازارچه صنایع دستی است که بازدید از آن هم درس تاریخ می‌دهد و هم چشم‌اندازی ۳۶۰ درجه از شهر و کوه‌های زاگرس هدیه می‌کند. برخلاف بسیاری از قلعه‌های تاریخی ایران که بیرون شهر مانده‌اند، اینجا وسط شهر است و مسیر رسیدن به آن بخش ساده سفر می‌شود.</p>
