<h2>چرا قلعه فلک‌الافلاک دیدنیِ شاخص لرستان است؟</h2>
<ul>
<li><strong>دژ ساسانی با پیشینه‌ای کهن:</strong> هسته اولیه قلعه به دوره ساسانی نسبت داده می‌شود و در گذر تاریخ محل حکومت آل بویه، اتابکان لر کوچک، والیان صفوی و قاجاری بوده است.</li>
<li><strong>معماری هشت‌برجی با دو صحن:</strong> پلان بنا هشت‌ضلعی نامنظم است و هشت برج، دو حیاط مستطیل‌شکل، تالارها و جان‌پناه‌ها از اجزای ساختاری آن‌اند.</li>
<li><strong>موزه‌های غنی درون قلعه:</strong> موزه مردم‌شناسی و موزه باستان‌شناسی لرستان با مفرغ‌های معروف، اشیای تاریخی و صحنه‌های بازسازی‌شده زندگی مردم منطقه.</li>
<li><strong>چشم‌انداز ۳۶۰ درجه شهر:</strong> موقعیت قلعه بر تپه‌ای طبیعی، دیدی پانورامیک از خرم‌آباد، رودخانه شهر و کوه‌های اطراف مانند هشتادپهلو و مخمل‌کوه می‌سازد.</li>
<li><strong>دسترسی شهری آسان:</strong> قلعه در خیابان امام خمینی (۱۲ برجی) و در مرکز شهر قرار دارد و با تاکسی و وسایل حمل‌ونقل شهری در دسترس است.</li>
</ul>

<h2>شناسنامه سریع قلعه</h2>
<ul>
<li>مساحت بنا: حدود ۵۳۰۰ متر مربع · شکل پلان: هشت‌ضلعی نامنظم</li>
<li>هشت برج، دو صحن مستطیل‌شکل، چهار تالار بزرگ و صدها کنگره و جان‌پناه</li>
<li>بلندترین دیوار: حدود ۲۲٫۵ متر تا سطح تپه</li>
<li>محوطه باستانی: حدود ۴۰۰ در ۳۰۰ متر · ارتفاع تپه با احتساب دیوارها: حدود ۴۰ متر از خیابان‌های اطراف</li>
<li>ورودی: جبهه شمالی، در برج جنوب‌غربی</li>
<li>چاه قلعه: عمقی حدود ۴۲ متر که به چشمه گلستان در دامنه شمالی تپه مرتبط بوده است</li>
<li>ثبت ملی: شماره ۸۸۳ در فهرست آثار ملی ایران</li>
</ul>

<h2>دژ شاپورخواست؛ مروری بر تاریخ</h2>
<p>نام قدیمی قلعه، دژ شاپورخواست است؛ بازمانده شهری به نام شاپورخواست که در حوالی خرم‌آباد امروزی ساخته شده بود. در روایت‌های تاریخی، این دژ در دوره ساسانی کاربرد حکومتی و نظامی داشته و گفته می‌شود اسرای رومی در آن نگهداری می‌شدند. پس از دوران ساسانی هم قلعه خالی نماند: در قرن چهارم هجری مقر حکومت آل حسنویه و در زمان آل بویه گنجور آن سلسله بود، مدتی به خزانه خاندان بدر تبدیل شد و در دوره صفویه محل حکومت والیان لرستان بود.</p>
<p>در دوره قاجار، محمدعلی‌میرزای دولتشاه قلعه را مرمت کرد و بخش‌هایی مانند دیوان‌خانه و سربازخانه به آن اضافه شد؛ از همان دوره نام فلک‌الافلاک (به معنای سپهر سپهران) بر آن ماند. در دوره پهلوی، قلعه به پادگان نظامی و زندان سیاسی تبدیل شد و این کاربری تا سال ۱۳۴۷ ادامه داشت. سرانجام در سال ۱۳۴۹ از ارتش به فرهنگ و هنر واگذار و به شماره ۸۸۳ در فهرست آثار ملی ثبت شد و از سال ۱۳۵۴ با راه‌اندازی موزه مردم‌شناسی و مفرغ‌های لرستان، به موزه تبدیل شد.</p>

{{GALLERY:overview}}

<h2>معماری؛ هشت برج، دو صحن و صدها کنگره</h2>
<p>در ساخت قلعه از خشت، آجر قرمز بزرگ، سنگ و ملات گچ و آهک استفاده شده و پی بنا روی صخره‌ای طبیعی نشسته است؛ در راهروهای قلعه هنوز بخش‌هایی از همان صخره تراش‌نخورده دیده می‌شود. هر صحن را چهار برج احاطه کرده است: دو برج در شمال و شمال‌غربی و دو برج در جنوب‌غربی و جنوب. حیاط دوم ساختاری شبیه حیاط اول دارد و در چهار سوی آن تالارهای بزرگ ساخته شده که به یکدیگر راه دارند.</p>
<p>روایت‌های محلی و اسناد تاریخی از بارویی قدیمی‌تر، دولایه و خشتی با دوازده برج پیرامون بنای امروزی خبر می‌دهند؛ به همین دلیل قلعه را «دوازده‌برجی» هم می‌نامند. برج آبی کنار رودخانه، گریزگاه اضطراری در حیاط دوم و چاه ۴۲ متری قلعه که به چشمه گلستان می‌رسید، سه راه‌حل هوشمندانه تأمین آب و امنیت در این دژ بوده‌اند.</p>

<h2>درون قلعه امروز؛ موزه‌ها و تجربه بازدید</h2>
<p>بازدید از فلک‌الافلاک فقط دیدن دیوار و برج نیست. درون مجموعه، موزه مردم‌شناسی و باستان‌شناسی لرستان فعال است؛ مفرغ‌های لرستان، اشیای باستانی، سنگ‌قبرها و صحنه‌های بازسازی‌شده زندگی مردم منطقه از دیدنی‌های آن‌اند. چای‌خانه سنتی، بازارچه صنایع دستی و آزمایشگاه مرمت اشیا هم بخش‌های دیگری از تجربه بازدید هستند. برنامه پیشنهادی این است که ابتدا محوطه و برج‌ها را ببینید، بعد وارد موزه‌ها شوید و در پایان، از بلندی قلعه چشمانداز شهر را تماشا کنید.</p>

<h2>مسیر دسترسی</h2>
<p>قلعه در مرکز خرم‌آباد و در خیابان امام خمینی (معروف به خیابان ۱۲ برجی) قرار دارد. با خودروی شخصی از خیابان امام وارد مسیر ۱۲ برجی شوید؛ پس از عبور از کنار رودخانه خرم‌آباد و پل تاریخی شاپوری، به محدوده قلعه می‌رسید. پارکینگ عمومی نزدیک قلعه وجود دارد، اما در تعطیلات و ساعات شلوغ پر می‌شود. با تاکسی از هر نقطه شهر می‌توان به قلعه رسید؛ از فرودگاه خرم‌آباد هم با تاکسی به مرکز شهر می‌آیید. از تهران، مسیر تهران – سلفچگان – اراک – بروجرد – خرم‌آباد حدود ۴۵۰ کیلومتر و حدود ۵ تا ۶ ساعت است. صبح‌های زودتر و روزهای غیرتعطیل، تجربه راحت‌تری می‌دهند.</p>

<h2>ساعات بازدید و بلیت</h2>
<p>ساعات بازدید و وضعیت پذیرش ممکن است با فصل، مناسبت‌ها و برنامهٔ مجموعه تغییر کند. ورود به قلعه بلیت‌دار است و نرخ آن متغیر است؛ پیش از سفر، ساعت و تعرفهٔ روز را از مرجع رسمی، خود مجموعه یا سامانهٔ ملی سفر (۰۹۶۲۹) استعلام کنید.</p>

<h2>بهترین زمان بازدید</h2>
<p>بهترین زمان بازدید، بهار و اوایل پاییز است؛ در این فصول هوای خرم‌آباد معتدل است و گشت‌وگذار در محوطه لذت‌بخش می‌شود. بهار طبیعت اطراف شهر را سرسبز می‌کند، اما تعطیلات نوروزی پرازدحام‌ترین روزهای قلعه است. پاییز خلوت‌تر و خنک‌تر است. در تابستان، صبح‌های زود یا عصرها را انتخاب کنید و در زمستان، روزهای آفتابی و ساعت میانی روز را. برای عکاسی، ساعت‌های پایانی بعدازظهر و نور کم و گرم غروب بهترین نور را روی آجرهای قلعه می‌اندازد.</p>

{{GALLERY:night}}

<h2>چشم‌انداز و عکاسی</h2>
<p>تپه قلعه بهترین سکوی تماشای خرم‌آباد است: چشمانداز شهر، رودخانه و کوه‌های اطراف از بالای برج‌ها یک قاب کامل می‌سازد. از بیرون هم قلعه در بسیاری از خیابان‌های مرکز شهر و از پل‌های اطراف دیده می‌شود و در شب، نورپردازی، چهره دیگری به آن می‌دهد. در محوطه و موزه‌ها قواعد عکاسی را رعایت کنید؛ در بخش‌هایی ممکن است فلاش یا سه‌پایه ممنوع باشد.</p>
{{GALLERY:crenellations}}

<h2>مناسب چه کسانی است و دسترسی‌پذیری</h2>
<ul>
<li><strong>علاقه‌مندان تاریخ و معماری:</strong> برای دیدن یک دژ چندلایه با آثار ساسانی، صفوی و قاجاری، این قلعه انتخاب اول لرستان است.</li>
<li><strong>موزه‌دوستان و گردشگران فرهنگی:</strong> مفرغ‌های لرستان و مجموعه‌های مردم‌شناسی، بازدید را به یک درس فرهنگ تبدیل می‌کند.</li>
<li><strong>عکاسان:</strong> چشمانداز پانورامیک، آجرهای کهنه و نورپردازی شب، سوژه‌های متنوعی می‌دهد.</li>
<li><strong>خانواده‌ها:</strong> مسیرهای داخلی و محوطه برای پیاده‌روی خانوادگی مناسب است.</li>
</ul>
<p><strong>دسترسی‌پذیری:</strong> چون قلعه روی تپه قرار دارد و مسیرهای داخلی پله و شیب دارند، بازدید با ویلچر یا برای سالمندان ممکن است دشوار باشد؛ در این حالت برنامه را کوتاه‌تر و با استراحت‌های بیشتر ببندید و پیش از حرکت درباره مسیرهای ساده‌تر ورود بپرسید.</p>

<h2>نکات ایمنی و مسئولانه</h2>
<ul>
<li><strong>کفش مناسب:</strong> پله‌ها و سطوح سنگی قلعه را با کفش راحت و غیرلغزنده طی کنید.</li>
<li><strong>آب و خوراکی:</strong> در محوطه داخلی امکانات محدود است؛ آب همراه داشته باشید.</li>
<li><strong>لمس نکنید:</strong> دیوارهای آجری و کاشی‌کاری‌ها در برابر لمس مداوم آسیب‌پذیرند؛ به آثار و ویترین‌ها دست نزنید.</li>
<li><strong>سکوت موزه:</strong> فضای موزه برای تماشا و مطالعه است؛ صدای بلند و دویدن، تجربه دیگران را خراب می‌کند.</li>
<li><strong>زباله:</strong> فقط در سطل‌های تعیین‌شده؛ محوطه تاریخی، سطل کافی ندارد، پس زباله خود را هم برگردانید.</li>
<li><strong>ساعات را بررسی کنید:</strong> برنامه بازدید را روی ساعات اعلام‌شده همان روز ببندید و برای روزهای تعطیل، حاشیه زمانی بگذارید.</li>
</ul>

<h2>برنامه پیشنهادی بازدید</h2>
<ol>
<li>صبح زود به قلعه بروید؛ برای محوطه، برج‌ها و عکاسی حدود یک ساعت وقت بگذارید.</li>
<li>سپس موزه مردم‌شناسی و باستان‌شناسی را ببینید؛ برای موزه‌ها حدود یک ساعت حساب کنید.</li>
<li>در چای‌خانه سنتی یا بازارچه صنایع دستی استراحت کنید.</li>
<li>در پایان، از بلندی قلعه چشمانداز شهر را ببینید و عکس بگیرید.</li>
<li>برای ادامه روز، پل شاپوری (پل شکسته)، مناره آجری، گرداب سنگی، دریاچه کیو و بام خرم‌آباد در فاصله نزدیک هستند؛ غار کلماکره هم برای علاقه‌مندان تاریخ گزینه جذابی است.</li>
</ol>

