<p><strong>دشت لاله‌های واژگون کوهرنگ</strong> در شهرستان کوهرنگِ استان چهارمحال و بختیاری و نزدیک روستای بنواستکی قرار دارد. این رویشگاه در گزارش‌های تاریخی با وسعت حدود ۳۶۰۰ هکتار معرفی شده و گل‌دهی آن معمولاً در بهار است؛ گسترهٔ فعلی و زمان دقیق گل‌دهی با وضعیت پوشش گیاهی، بارش و شرایط همان سال تفاوت می‌کند. دسترسی نیز تابع ضوابط حفاظتی روز است.</p>
<p>دشت در نزدیکی روستای بنواستکی و در ۱۲ کیلومتری شهر چلگرد قرار دارد. بخشی از آن به‌عنوان اثر طبیعی ملی زیر حفاظت است و در سال‌های اخیر به دلیل کاهش وسعت پوشش گیاهی، قرق و محدودیت‌هایی برای ورود گردشگران اعمال شده است؛ به همین دلیل پیش از هر سفر باید وضعیت روز منطقه را از منابع رسمی بپرسید.</p>
