<p><strong>تالاب انزلی</strong> در جنوب غربی دریای خزر و در استان گیلان، یکی از بزرگ‌ترین و مهم‌ترین زیستگاه‌های آب شیرین ایران است؛ پهنه‌ای حدود ۲۰ هزار هکتاری که از یک سو به کانال کشتیرانی بندر انزلی و دریای خزر می‌رسد و از سوی دیگر به شالیزارها و دشت‌های گیلان. این تالاب از سال ۱۳۵۴ در فهرست تالاب‌های بین‌المللی کنوانسیون رامسر ثبت شده است.</p>
<p>یازده رودخانهٔ اصلی و حدود سی رودخانهٔ فرعی، آب مزارع و دامنه‌های البرز را به این تالاب می‌رسانند و همین آب شیرین و پرغذا، آن را به خانهٔ بیش از صد گونه پرنده، حدود پنجاه گونه ماهی و صدها گونه گیاه آبزی تبدیل کرده است. شناخته‌شده‌ترین چهرهٔ تالاب، گل صورتی و سفید لاله مردابی (نیلوفر آبی) است که از اواخر خرداد تا پایان شهریور سطح آب را می‌پوشاند.</p>
