<p><strong>آبشار شوی</strong> یکی از آبشارهای شناخته‌شدهٔ زاگرس است؛ آب آن پس از بیرون‌آمدن از دهانهٔ غاری در کوهستان سرتنگ از دیواره‌ای بلند فرو می‌ریزد. ریزشگاه در نزدیکی روستای شوی، در بخش شهیونِ شهرستان دزفول و <a href="/province/khuzestan/">استان خوزستان</a> قرار دارد. مسیر ریلیِ شناخته‌شدهٔ بازدید از ایستگاه تله‌زنگ در محور دورود–اندیمشک می‌گذرد. آبشار در سال ۱۳۹۳ در فهرست آثار ملی ایران ثبت شده است.</p>
<p>نام «تله‌زنگ» که همراه نام این آبشار به کار می‌رود، از ایستگاه راه‌آهن تله‌زنگ در محور دورود–اندیمشک گرفته شده است. سفر ریلی از <a href="/city/dorud/">دورود</a> و پیاده‌روی کوهستانی از ایستگاه، یکی از مسیرهای شناخته‌شدهٔ دسترسی است؛ زمان حرکت قطارها و وضعیت مسیر را همان روز بررسی کنید. پیمایش طولانی و شرایط کوهستانی به آمادگی و برنامهٔ روشنِ رفت‌وبرگشت نیاز دارد.</p>
{{GALLERY:main}}

<h2>چرا آبشار شوی دیدنیِ شاخص این منطقه است؟</h2>
<ul>
<li><strong>خروج آب از دهانهٔ غار:</strong> معرفی‌های آبشار شوی، جریان آب از دهانهٔ غاری در کوهستان سرتنگ و سپس فرود آن از دیواره‌ای بلند را از ویژگی‌های این ریزشگاه می‌دانند.</li>
<li><strong>ریزشگاه در دل کوهستان:</strong> آب پس از عبور از دهانهٔ غار از دیواره‌ای بلند فرو می‌ریزد و چشم‌انداز آبشار را از بسیاری از مسیرهای زاگرس متمایز می‌کند.</li>
<li><strong>ثبت در فهرست آثار ملی:</strong> ثبت ملی در ۲۹ دی ۱۳۹۳ و جایگاه آن به‌عنوان ششمین اثر طبیعی ملی استان خوزستان — پس از خلیج فارس، رود کارون، سرو زربین پیر سلیم، چشمه‌های قیر و تشکوه — نشان‌دهندهٔ ارزش ملی این اثر است.</li>
<li><strong>دسترسی ریلی:</strong> یکی از مسیرهای گزارش‌شده از ایستگاه تله‌زنگ در محور دورود–اندیمشک آغاز می‌شود؛ پس از پیاده‌شدن، ادامهٔ مسیر کوهستانی است و نیاز به برنامه‌ریزی جداگانه دارد.</li>
<li><strong>طبیعت دست‌نخوردهٔ پیرامون:</strong> پوشش گیاهی اطراف آبشار از درختان بید، انجیر، مو، زبان‌گنجشگ، افرا، کیکم و بلوط تشکیل شده و در زیر ریزشگاه، گیاه سیاه‌وشان و دیگر گیاهان آب‌دوست روی دیواره‌های مرطوب می‌رویند.</li>
</ul>

<h2>موقعیت آبشار شوی</h2>
<p>ریزشگاه آبشار در نزدیکی روستای شوی، از توابع بخش شهیون و دهستان امامزاده سید محمود <strong>شهرستان دزفول در استان خوزستان</strong> قرار دارد و آب آن پس از عبور از کوه‌ها و دره‌ها به رود دز و در نهایت به دریاچهٔ شهیون می‌ریزد. با این حال، ایستگاه راه‌آهن تله زنگ — که خود از توابع شهرستان اندیمشک است — نزدیک‌ترین نقطهٔ دسترسی به آبشار به شمار می‌آید و از سمت دورود نهمین و از سمت اندیمشک ششمین ایستگاه خط لرستان است.</p>
<p>با وجود قرارگرفتن ریزشگاه در خوزستان، مسیر ریلیِ بازدید از محور دورود–اندیمشک و ایستگاه تله‌زنگ می‌گذرد. بهتر است پیش از حرکت، وضعیت قطار و مسیر زمینی را جداگانه بررسی کنید؛ مبدأ سفر، محل اداری خودِ آبشار نیست.</p>
{{GALLERY:wide}}

<h2>مسیر دسترسی</h2>
<h3>مسیر یکم: قطار تا ایستگاه تله زنگ (مسیر کلاسیک)</h3>
<p>در مسیر ریلیِ شناخته‌شده، از دورود با قطار محلی خط دورود–اندیمشک به ایستگاه تله‌زنگ (نام رسمی ایستگاه شهید چراغی) می‌رسند؛ این ایستگاه از سمت دورود نهمین و از سمت اندیمشک ششمین ایستگاه معرفی شده است. از ایستگاه، مسیر کوهستانی به سمت روستای شوی و ریزشگاه ادامه دارد؛ برخی منابع فاصلهٔ پیمایش را ۱۰ تا ۱۵ کیلومتر و زمان آن را چند ساعت ذکر می‌کنند. در گزارش‌ها از رود سزار و پل راه‌آهن تله‌زنگ نیز نام برده شده، اما این به‌تنهایی ثابت نمی‌کند که عبور از آب در همهٔ مسیرها لازم یا ایمن است. مسیر دقیق و وضعیت آب را همان روز از راهنمای محلی بپرسید و در صورت نامطمئن‌بودن جریان، عبور نکنید. برنامهٔ حرکت قطار را نیز پیش از سفر استعلام کنید.</p>
<h3>مسیر دوم: از سمت دزفول و روستای شوی</h3>
<p>مسیر جایگزین از سمت دزفول و سردشت با خودروی آفرود تا نزدیکی روستای شوی است و پس از آن حدود ۲ تا ۳ ساعت پیاده‌روی در پیش دارید. این مسیر کوتاه‌تر است اما به خودروی مناسب و آشنایی با جاده‌های خاکی منطقه نیاز دارد. در هر دو مسیر، پیش از حرکت دربارهٔ وضعیت آب رودخانه و باز بودن راه از اهالی روستای شوی یا راهنمای محلی بپرسید.</p>
{{GALLERY:route}}

<h2>بهترین زمان بازدید</h2>
<ul>
<li><strong>اواخر زمستان و بهار (اسفند تا خرداد):</strong> آبشار معمولاً پرآب‌تر است، اما بارش و افزایش جریان می‌تواند پیمایش را دشوار یا ناایمن کند؛ شرایط روز را پیش از حرکت از منبع محلی بررسی کنید.</li>
<li><strong>تابستان:</strong> حجم آب کمتر اما هوا برای پیاده‌روی طولانی مطبوع‌تر؛ روزها گرم و شب‌های کوهستان خنک است.</li>
<li><strong>پاییز:</strong> رنگ‌های پاییزی بلوط‌های زاگرس و هوای پایدار؛ برای عکاسی از دیواره‌ها بهترین فصل است.</li>
<li><strong>زمستان:</strong> سرما، برف و یخ‌زدگی می‌تواند دسترسی را دشوار کند؛ پیش‌بینی هوا و وضعیت مسیر را بررسی کنید و در شرایط نامناسب سفر را به تعویق بیندازید.</li>
</ul>

<h2>این سفر برای چه کسانی مناسب است؟</h2>
<ul>
<li><strong>طبیعت‌گردان آماده:</strong> پیمایش طولانی و ناهمواری مسیر به آمادگی بدنی، برنامه‌ریزی و آگاهی از شرایط کوهستان نیاز دارد.</li>
<li><strong>گروه‌های همراه با راهنمای محلی:</strong> برای نخستین بازدید، همراهی راهنمای آشنا به مسیر تله زنگ اکیداً توصیه می‌شود.</li>
<li><strong>عکاسان طبیعت:</strong> ریزشگاه، دهانهٔ غار و دیواره‌های مرطوب از عناصر قابل ثبت در عکس‌اند؛ وضعیت نور و امکان دسترسی را پیش از ورود بررسی کنید.</li>
<li><strong>خانواده‌ها و افراد مبتدی:</strong> این مقصد به‌دلیل نبود امکانات، نبود پوشش تلفن همراه و دشواری مسیر، برای کودکان، سالمندان و سفرهای بدون برنامه مناسب نیست.</li>
</ul>

<h2>نکات ایمنی و محیط‌زیستی</h2>
<ul>
<li>بخش بزرگی از مسیر خارج از پوشش شبکهٔ تلفن همراه است؛ پیش از حرکت، برنامه و زمان بازگشت را با یک نفر در شهر در میان بگذارید.</li>
<li>هیچ فروشگاه، آب آشامیدنی یا امکانات رفاهی در مسیر و پای آبشار وجود ندارد؛ آب و خوراکی کافی همراه ببرید.</li>
<li>اگر رودخانه پرآب است یا عمق و جریان آن روشن نیست، از عبور صرف‌نظر کنید و به مسیر امن بازگردید؛ از طناب یا راهکار دست‌ساز برای عبور استفاده نکنید.</li>
<li>سنگ‌های زیر ریزشگاه به‌دلیل رطوبت و جلبک بسیار لغزنده‌اند؛ فاصلهٔ ایمن با لبهٔ پرتگاه را حفظ کنید.</li>
<li>آبشار در فهرست آثار ملی ثبت شده است؛ چیدن گیاهان، روشن کردن آتش روی پوشش گیاهی و حک کردن روی صخره‌ها ممنوع است.</li>
<li>همهٔ زباله‌های خود را بازگردانید و پیش از ترک محل، محل استراحت را پاک‌تر از زمان ورود تحویل بدهید.</li>
</ul>

<h2>برنامهٔ پیشنهادی بازدید</h2>
<ul>
<li><strong>روز پیش از سفر:</strong> استعلام زمان حرکت قطار محلی دورود–اندیمشک، بررسی وضعیت هوا و هماهنگی با راهنمای محلی یا اهالی روستای شوی.</li>
<li><strong>زمان حرکت:</strong> قطارِ مناسب را بر اساس برنامهٔ منتشرشدهٔ همان روز انتخاب کنید؛ پس از پیاده‌شدن در ایستگاه تله‌زنگ، پیش از ادامهٔ مسیر شرایط و زمان بازگشت را دوباره بررسی کنید.</li>
<li><strong>در مسیر:</strong> تنها در صورت ایمن‌بودن مسیر و روشن‌بودن وضعیت آب ادامه دهید؛ اگر عمق یا جریان رودخانه نامطمئن یا پرقدرت است، عبور نکنید و به نقطهٔ امن برگردید.</li>
<li><strong>بازگشت:</strong> زمان کافی برای بازگشت به ایستگاه و رسیدن در روشنایی بگذارید؛ بازدید از مقصدهای فرعی را فقط در صورت باقی‌ماندن حاشیهٔ امن زمانی انجام دهید.</li>
<li><strong>شب‌مانی:</strong> آن را فقط پس از تأیید مجازبودن و هماهنگی با مرجع محلی در برنامه بگنجانید؛ داشتن تجهیزات به‌تنهایی جایگزین مجوز یا ارزیابی شرایط نیست.</li>
</ul>

<h2>پیشنهاد عکاسی</h2>
<ul>
<li><strong>نمای کامل ریزشگاه:</strong> از فاصلهٔ امن و با قاب باز، آبشار و دیواره‌های پیرامون را در یک تصویر ثبت کنید.</li>
<li><strong>دهانهٔ غار:</strong> عکاسی از نقطه‌ای که آب از دل صخره بیرون می‌آید؛ اختلاف نور زیاد است و عکاسی با فایل خام (RAW) توصیه می‌شود.</li>
<li><strong>زیر ریزشگاه:</strong> قطرات معلق در هوا و رنگین‌کمان‌های کوچک؛ برای محافظت از لنز، فیلتر یا دستمال همراه داشته باشید.</li>
<li><strong>پوشش گیاهی:</strong> سیاه‌وشان و گیاهان آب‌دوست روی دیواره‌های مرطوب، سوژه‌ای عالی برای عکاسی ماکرو.</li>
<li><strong>مسیر و پل تله زنگ:</strong> پل راه‌آهن تله زنگ و دره‌های مسیر، بهترین قاب‌ها را در نور طلایی صبح و نزدیک غروب می‌دهند.</li>
</ul>
{{GALLERY:second}}

<h2>مقصدهای مکمل سفر</h2>
<ul>
<li><a href="/attraction/bisheh-waterfall-dorud/">آبشار بیشه</a>؛ آبشاری در نزدیکی ایستگاه بیشه در همان محور راه‌آهن که دسترسی بسیار ساده‌تری دارد.</li>
<li><a href="/attraction/gahar-lake-dorud/">دریاچه گهر</a>؛ دریاچهٔ کوهستانی دامنهٔ اشترانکوه در جنوب شرقی دورود.</li>
