		'content'      => <<<'SA_ART'
<p>در دشتِ شمال غربی <a href="/city/torbatjam/">شهرستان تربت جام</a>، جایی که بافت روستاهای خراسان هنوز خانه‌های خشتی و گذرهای باریک خود را نگه داشته، روستای <strong>لنگر</strong> یکی از کم‌شناخته‌شده‌ترین بناهای تاریخی <a href="/province/razavi-khorasan/">خراسان رضوی</a> را در خود جا داده است: <strong>آرامگاه شاه قاسم انوار</strong>. اینجا فقط یک مقبره نیست؛ ردِ یک خانقاه است — جایی که عارف و شاعری از سده‌های هشتم و نهم هجری، سال‌های پایانی عمرش را در آن گذراند و پس از مرگ، خودش به محور همان بنا تبدیل شد.</p>

<h2>چرا آرامگاه قاسم انوار دیدنیِ شاخص تربت جام است؟</h2>
<ul>
<li><strong>یک روایتِ کاملِ تصوف ایرانی در یک بنا:</strong> خانقاه، گنبد و باغ، هر سه در یک مجموعه هستند.</li>
<li><strong>معماری تیموری:</strong> بنای مقبره به فرمان امیر علی‌شیر نوایی، ادیب و وزیرِ دربار تیموری، ساخته شد؛ نشانه‌ای از احترام گستردهٔ آن دوره به عارفان.</li>
<li><strong>ثبت ملیِ زودهنگام:</strong> این اثر از ۱۶ اردیبهشت ۱۳۵۴ در فهرست آثار ملی ایران است.</li>
<li><strong>همسایگی با دو مقصد بزرگ:</strong> آرامگاه شیخ احمد جامی و مسجدهای تاریخی تربت جام در همین سفر قابل دیدار است.</li>
</ul>

<h2>شاه قاسم انوار که بود؟</h2>
<p>قاسم انوار از عارفان و شاعران سدهٔ هشتم و آغاز سدهٔ نهم هجری است. منابع، سالِ درگذشت او را ۸۳۷ قمری و سنش را هنگام مرگ حدود هشتاد سال ثبت کرده‌اند. به گفتهٔ تذکره‌ها، او در آغاز به صدرالدین (فرزند صفی‌الدین اردبیلی) ارادت داشت و بعدها با صدرالدین علی یمنی، از یاران اوحدالدین کرمانی، همراه شد. سفر او به بلخ و سمرقند و بازگشتش به خرگردِ جام، فصل دوم زندگی‌اش را ساخت: در همین منطقه خانقاهی بنیاد کرد و سال‌های آخر را در آن گذراند. شعرش پر از اشاره‌های قرآنی و تعبیرهای مشایخ تصوف است و از میان شاعران پیشین، بیشترین نزدیکی را به مولانا، حافظ و سنایی دارد.</p>

<h2>موقعیت و مسیر دسترسی</h2>
<p>آرامگاه در روستای لنگر، در شمال غربی تربت جام و در دهستان میان‌جام قرار دارد. منابع فاصلهٔ آن از شهر تربت جام را <strong>۲۴ تا ۲۷ کیلومتر</strong> نوشته‌اند و مسیر تا نزدیکی روستا آسفالته است؛ خودروی سواری به راحتی می‌رسد. اگر از سمت تربت حیدریه یا مرزهای غربی استان می‌آیید، شهرهای مسیر مثل <a href="/city/torbat-heydarieh/">تربت حیدریه</a> و <a href="/city/taybad/">تایباد</a> گزینه‌های اتراق و سوخت‌گیری‌اند. برای خودِ روستا، پرس‌وجوی محلی از اهالی سریع‌ترین راه پیدا کردن باغِ آرامگاه است؛ جاده‌های بین مزارع را بدون راهنما نروید.</p>

<h2>در مجموعه چه می‌بینیم؟</h2>
<p>آن‌چه امروز می‌بینید، ادامهٔ همان خانقاهِ سه‌گانهٔ میان کوچه‌ها، گنبد و باغ است. ساختار بنا در منابع «نمونه‌ای بارز از معماری اواخر دورهٔ تیموری» توصیف شده و در طول مرمت‌ها بخش‌هایی از خودِ بافت روستا هم حفظ شده است. باغ پیرامون آرامگاه فضای سایه‌داری برای نشستن می‌دهد و قاب عکاسی خوبی از گنبد و درخت‌های کهن می‌سازد. اگر به‌دنبال بافتِ زندگی محلی هم هستید، گذرهای خشتی روستا و باغ‌های اطراف، بخشی از همین تجربه‌اند.</p>

<h2>بهترین زمان بازدید</h2>
<p>دشت جام تابستان‌های گرم و زمستان‌های سرد دارد؛ بنابراین بهار (فروردین تا اوایل اردیبهشت) و پاییز (مهر و آبان) راحت‌ترین زمان‌ها برای این سفر هستند. صبح‌های زود یا پیش از غروب، هم هوا معتدل‌تر است و هم نورِ مورب، نتیجهٔ بهتری برای عکاسی می‌دهد. در زمستان مسیر آسفالته معمولاً باز است، اما برای باز بودن ضریح‌خانه پیش از حرکت پرس‌وجو کنید.</p>

<h2>نکات بازدید</h2>
<ul>
<li>این بنا تاریخی و مذهبی است؛ آرام و پرهیز از صدای بلند، حقِ اهالی و زائران محلی است.</li>
<li>از بالا رفتن روی لبه‌ها، جرزها و بخش‌های آسیب‌پذیرِ بنا خودداری کنید.</li>
<li>در تابستان آب، کلاه و ضدآفتاب لازم است؛ ساعات ظهر را برای بازدید انتخاب نکنید.</li>
<li>هزینهٔ ورود یا خدمات محلی را پیش از بازدید از متولی یا مرجع محلی جویا شوید؛ اگر کسی در بازدید همراهی‌تان کرد، دربارهٔ هر هزینه یا انعام از خود او بپرسید.</li>
<li>عکس‌گرفتن از مراسم و افراد محلی، بدون اجازه انجام نشود.</li>
</ul>

