<h2>کجاست و چه نامی دارد؟</h2>
<p>قلعه در غرب بشرویه بر کوهی با ارتفاع حدود <strong>۴۰۰ متر از سطح زمین</strong> (و در منابع، ۱٬۲۵۰ متر از سطح دریا) قرار دارد. منابع فاصلهٔ آن از شهر را متفاوت نوشته‌اند — ۱۰، ۱۲ و ۱۴ کیلومتر — و موقعیتش را ۶ کیلومتری شمال شرقی روستای <strong>رقه</strong> ثبت کرده‌اند؛ همین نام باعث شده در بعضی منابع «قلعه دختر رقه» خوانده شود. کنار مسیر، آسیاب آبیِ کهنی به نام «آسیاب دهنه» هم هست که نشان می‌دهد این پهنه در گذشته مسیر آب و کشت بوده است.</p>

<h2>روایت‌های قدمت</h2>
<p>دربارهٔ زمان ساخت قلعه، منابع یک حرف نمی‌زنند و همین، بخشی از جذابیت آن است:</p>
<ul>
<li><strong>روایت ساسانی:</strong> مصالح و ملات (سنگ، گچ و آهک)، شکل پی‌سازی و پوشش اتاق‌ها، قلعه را در خانوادهٔ قلعه‌های «دختر»یِ بازمانده از دورهٔ ساسانی می‌نشاند؛ خانواده‌ای که نمونه‌هایش را در فیروزآباد، بجستان و شوشتر هم می‌بینیم. در یک مصاحبهٔ مسئول میراث فرهنگی شهرستان، قدمت بنا در حدود <strong>۱٬۵۰۰ تا ۲٬۰۰۰ سال</strong> و مربوط به پیش از اسلام دانسته شده است.</li>
<li><strong>روایت اسماعیلی:</strong> گروهی از منابع، ساخت یا دست‌کم استفادهٔ مجدد از قلعه را به فداییان اسماعیلی در دورهٔ سلجوقی نسبت می‌دهند؛ فرقه‌ای که در ناحیهٔ تون و طبس پناهگاه‌هایی داشت و جادهٔ ارتباطی تون به طبس از کنار همین محل می‌گذشت.</li>
<li><strong>لایهٔ متأخر:</strong> برخی نوشته‌ها از کاربرد قلعه تا دورهٔ افشاریه و زمان نادرشاه هم یاد می‌کنند و آن را نیازمند پژوهش بیشتر می‌دانند.</li>
</ul>
<p>پس آن‌چه مسلم است، این است که قلعه لایه‌های زمانی مختلفی را دیده و یافته‌های باستان‌شناسی، زندگی پیش از اسلام در آن را تقویت می‌کند.</p>

<h2>در قلعه چه می‌بینیم؟</h2>
<ul>
<li><strong>دیوارهای خشک‌چین در چهار سطح:</strong> به‌واسطهٔ ملات مقاوم، دیواره‌ها در چند ترازِ پشت‌سرهم بالا می‌روند و به فضای مرکزی قلعه می‌رسند.</li>
<li><strong>برج‌های دیده‌بانی:</strong> برج‌های مدور با ارتفاع تقریبی ۳ تا ۴ متر و دیوارهای به‌هم‌پیوسته که میدان دید چهارسویه می‌ساخته‌اند.</li>
<li><strong>دالان‌ها و تالارها:</strong> دالان‌های عریض و مسقف، اتاق‌های وسیع و اتاق شاه‌نشین.</li>
<li><strong>آب‌انبارها و انبار آذوقه:</strong> در منابع از چهار آب‌انبار در قلعه یاد شده که تنها یکی سالم مانده و پوشش گنبدیِ میانی‌اش از بین رفته است؛ فضای ذخیرهٔ آذوقه هم برای محاصره طراحی شده بود.</li>
</ul>

<h2>مسیر دسترسی و نکات بازدید</h2>
<p>از شهر بشرویه به سمت غرب و روستای رقه حرکت کنید؛ مسیر خودرو تا نزدیکی دامنه پیش می‌رود و بخش پایانی صعود پیاده است. صعود ساده نیست: <strong>سه ضلع قلعه پرتگاه است و تنها راه از سمت جنوب</strong> می‌گذرد، پس تنها نروید، کفش کوهستان بپوشید و در روزهای بارانی یا بادی شدید بالا نروید. از راه رفتن روی دیوارها و طاق‌های نیم‌فروریخته خودداری کنید؛ این بنا تاریخی است، نه مسیر کوه‌نوردی. برنامه را طوری بچینید که پیش از تاریکی به پایین برگردید و آب همراه داشته باشید.</p>

